import { Controller, Logger, UsePipes, UseFilters } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { ProjectsService } from '../projects/projects.service';
import { UserService } from '../user/user.service';
import { ContechRole } from '../generated/client';
import { RpcExceptionFilter } from '../common/filters/rpc-exception.filter';
import { JoiValidationPipe } from '../common/pipes/joi-validation.pipe';
import { AdminDashboardSchema, ListProfilesSchema } from './admin.validation';

@Controller()
@UseFilters(RpcExceptionFilter)
export class AdminController {
  private readonly logger = new Logger(AdminController.name);

  constructor(
    private readonly projectsService: ProjectsService,
    private readonly userService: UserService,
  ) {}

  @MessagePattern({ cmd: 'get_admin_dashboard' })
  @UsePipes(new JoiValidationPipe(AdminDashboardSchema))
  async getDashboard(@Payload() payload: Record<string, any>) {
    const { user } = payload;
    this.logger.log(
      `Fetching admin dashboard data (requested by: ${user.firebaseId})`,
    );

    try {
      const profile = await this.userService.getOrCreateProfile(user);
      if (profile.role !== 'ADMIN') {
        throw new Error('Unauthorized: Admin access required');
      }

      const stats = await this.projectsService.getProjectStats(user);

      const [totalClients, totalContractors] = await Promise.all([
        this.userService.countByRole(ContechRole.CLIENT),
        this.userService.countByRole(ContechRole.CONTRACTOR),
      ]);

      return {
        projectStats: stats,
        users: {
          clients: totalClients,
          contractors: totalContractors,
        },
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      const errorStack = error instanceof Error ? error.stack : undefined;
      this.logger.error(
        `Failed to fetch admin dashboard for user ${user.firebaseId}: ${errorMessage}`,
        errorStack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'list_contech_users' })
  @UsePipes(new JoiValidationPipe(ListProfilesSchema))
  async listUsers(@Payload() payload: Record<string, any>) {
    const { user, role, page, pageSize } = payload;
    this.logger.log(
      `Listing users with role: ${role || 'all'} (requested by admin: ${user.firebaseId})`,
    );

    try {
      const adminProfile = await this.userService.getOrCreateProfile(user);
      if (adminProfile.role !== 'ADMIN') {
        throw new Error('Unauthorized: Admin access required');
      }

      return await this.userService.findProfilesByRole(role, page, pageSize);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      const errorStack = error instanceof Error ? error.stack : undefined;
      this.logger.error(
        `Failed to list users for admin ${user.firebaseId}: ${errorMessage}`,
        errorStack,
      );
      throw error;
    }
  }
}

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { UserService } from '../user/user.service';

@Injectable()
export class ConTechProfileGuard implements CanActivate {
  constructor(private userService: UserService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToRpc().getData() as Record<string, any>;
    const user = request.user;

    if (!user) {
      throw new UnauthorizedException('No user found in request');
    }

    // Ensure user has ConTech profile
    try {
      const profile = await this.userService.getOrCreateProfile(user);
      request.contechProfile = profile;
      return true;
    } catch (error) {
      throw new UnauthorizedException('Failed to get ConTech profile');
    }
  }
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { RpcException } from '@nestjs/microservices';
import { ROLES_KEY } from './roles.decorator';

@Injectable()
export class RoleGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    // Get the required roles from the @Roles() decorator
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (!requiredRoles) {
      // If no roles are specified, allow access.
      return true;
    }

    const data = context.switchToRpc().getData();

    // Get the contechProfile attached by the ConTechProfileGuard
    const { contechProfile } = data;

    if (!contechProfile || !contechProfile.role) {
      // This should ideally never happen if the ConTechProfileGuard ran first
      throw new RpcException('User profile or role not found.');
    }

    // Check if the user's role is included in the list of required roles.
    const hasRequiredRole = requiredRoles.some(
      (role) => contechProfile.role === role,
    );

    if (!hasRequiredRole) {
      throw new RpcException(
        'You do not have the required permissions to perform this action.',
      );
    }

    return true;
  }
}

import {
  Controller,
  UseGuards,
  UsePipes,
  Logger,
  UseFilters,
} from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { ClientReportService } from './client-report.service';
import { CreateClientReportDto } from './dto/create-client-report.dto';
import { AuthenticatedUser } from '../user/user.service';
import { ConTechProfileGuard, RoleGuard, Roles } from '../auth';
import { RpcExceptionFilter } from '../common/filters/rpc-exception.filter';
import { JoiValidationPipe } from '../common/pipes/joi-validation.pipe';
import {
  CreateClientReportSchema,
  GetProjectReportsSchema,
  ReportIdSchema,
} from './client-report.validation';

@Controller()
@UseGuards(ConTechProfileGuard)
@UseFilters(RpcExceptionFilter)
export class ClientReportController {
  private readonly logger = new Logger(ClientReportController.name);
  constructor(private readonly clientReportsService: ClientReportService) {}

  @MessagePattern({ cmd: 'createClientReport' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  @UsePipes(new JoiValidationPipe(CreateClientReportSchema))
  async create(
    @Payload() payload: { dto: CreateClientReportDto; user: AuthenticatedUser },
  ) {
    this.logger.log(
      `Creating client report for project ID: ${payload.dto.projectId} by admin: ${payload.user.firebaseId}`,
    );
    try {
      return await this.clientReportsService.create(payload.dto, payload.user);
    } catch (error) {
      this.logger.error(
        `Failed to create client report for project ID ${payload.dto.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'findAllClientReportsByProjectId' })
  @UsePipes(new JoiValidationPipe(GetProjectReportsSchema))
  async findAllByProjectId(
    @Payload() payload: { projectId: number; user: AuthenticatedUser },
  ) {
    // Controller expects 'id' in method but schema/payload might call it 'projectId'
    this.logger.log(
      `Fetching reports for project ID: ${payload.projectId} (requested by: ${payload.user.firebaseId})`,
    );
    try {
      return await this.clientReportsService.findAllByProjectId(
        payload.projectId,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to fetch reports for project ID ${payload.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'findOneClientReportById' })
  @UsePipes(new JoiValidationPipe(ReportIdSchema))
  async findOneById(
    @Payload() payload: { id: number; user: AuthenticatedUser },
  ) {
    this.logger.log(
      `Fetching report details for ID: ${payload.id} by user: ${payload.user.firebaseId}`,
    );
    try {
      return await this.clientReportsService.findOneById(
        payload.id,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to fetch report detail for ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }
}

// src/client-reports/client-reports.service.ts
import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service'; // Adjust the path to your Prisma service
import { CreateClientReportDto } from './dto/create-client-report.dto';
import { Prisma } from '../generated/client';
import { AuthenticatedUser, UserService } from '../user/user.service';

@Injectable()
export class ClientReportService {
  constructor(
    private prisma: PrismaService,
    private userService: UserService,
  ) {}

  async create(
    createClientReportDto: CreateClientReportDto,
    user: AuthenticatedUser,
  ) {
    const { projectId, summary, KPIs, title } = createClientReportDto;

    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
    });

    if (!project) {
      throw new NotFoundException(`Project with ID ${projectId} not found.`);
    }

    return this.prisma.clientReport.create({
      data: {
        projectId,
        summary,
        KPIs: KPIs as any,
      },
    });
  }

  async findAllByProjectId(projectId: number, user: AuthenticatedUser) {
    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
    });
    if (!project) throw new NotFoundException('Project not found');

    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to view reports for this project.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view reports for this project.',
      );
    }

    return this.prisma.clientReport.findMany({
      where: {
        projectId: projectId,
      },
      orderBy: {
        generatedAt: 'desc', // Show the most recent reports first
      },
    });
  }

  async findOneById(reportId: number, user: AuthenticatedUser) {
    const report = await this.prisma.clientReport.findUnique({
      where: {
        id: reportId,
      },
      include: { Project: true },
    });

    if (!report) {
      throw new NotFoundException(
        `Client Report with ID ${reportId} not found.`,
      );
    }

    const project = (report as any).Project;
    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to view this report.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view this report.',
      );
    }

    return report;
  }
}

import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  v2 as cloudinary,
  UploadApiResponse,
  UploadApiErrorResponse,
  UploadApiOptions,
} from 'cloudinary';
import { Readable } from 'stream';

// Import Multer's file type directly
import { File as MulterFile } from 'multer';

// Define a type alias for Multer's file object for clarity
export type MulterFile = MulterFile;

@Injectable()
export class CloudinaryService {
  constructor(private readonly config: ConfigService) {
    // Constructor is now more concise using private readonly
    cloudinary.config({
      cloud_name: this.config.get('CLOUDINARY_CLOUD_NAME'),
      api_key: this.config.get('CLOUDINARY_API_KEY'),
      api_secret: this.config.get('CLOUDINARY_API_SECRET'),
    });
  }

  async uploadImage(
    file: MulterFile,
    options?: UploadApiOptions,
  ): Promise<UploadApiResponse> {
    // Enforce the resource_type as 'image' and merge with any provided options
    const uploadOptions: UploadApiOptions = {
      ...options,
      resource_type: 'image',
    };
    return this.uploadStream(file.buffer, uploadOptions);
  }

  async uploadRaw(
    file: MulterFile,
    options?: UploadApiOptions,
  ): Promise<UploadApiResponse> {
    // Enforce the resource_type as 'raw' and merge with any provided options
    const uploadOptions: UploadApiOptions = {
      ...options,
      resource_type: 'raw',
    };
    return this.uploadStream(file.buffer, uploadOptions);
  }

  private uploadStream(
    buffer: Buffer,
    options: UploadApiOptions,
  ): Promise<UploadApiResponse> {
    return new Promise((resolve, reject) => {
      const upload = cloudinary.uploader.upload_stream(
        options,
        (
          error: UploadApiErrorResponse | undefined,
          result: UploadApiResponse | undefined,
        ) => {
          if (error) {
            return reject(new InternalServerErrorException(error.message));
          }
          if (result) {
            resolve(result);
          } else {
            reject(
              new InternalServerErrorException(
                'No result returned from Cloudinary upload.',
              ),
            );
          }
        },
      );
      const readableStream = new Readable();
      const safeBuffer = Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer);
      readableStream.push(safeBuffer);
      readableStream.push(null);
      readableStream.pipe(upload);
    });
  }
}

import {
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
  ExceptionFilter,
} from '@nestjs/common';
import { RpcException } from '@nestjs/microservices';
import { Prisma } from '../../generated/client';
import { Observable, throwError } from 'rxjs';

/**
 * Centralized exception filter for Microservices.
 * Catches all errors and transforms them into a standardized RpcException object
 * that the API Gateway can properly deserialize.
 */
@Catch()
export class RpcExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(RpcExceptionFilter.name);

  catch(exception: any, host: ArgumentsHost): Observable<any> {
    let status = HttpStatus.INTERNAL_SERVER_ERROR;
    let message = 'Internal server error';
    let error = 'Internal Server Error';
    let details: any = null;

    // 1. Handle Nest HTTP Exceptions (e.g. ForbiddenException, NotFoundException)
    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const response = exception.getResponse() as any;

      if (typeof response === 'object') {
        message = Array.isArray(response.message)
          ? response.message[0]
          : response.message || exception.message;
        error = response.error || 'Http Error';
        details = response.details || null;
      } else {
        message = response;
        error = 'Http Error';
      }
    }
    // 2. Handle Prisma Client Errors (Database)
    else if (exception instanceof Prisma.PrismaClientKnownRequestError) {
      this.logger.error(
        `Prisma Error [${exception.code}]: ${exception.message}`,
      );

      switch (exception.code) {
        case 'P2002': // Unique constraint violation
          status = HttpStatus.CONFLICT;
          const target = (exception.meta?.target as string[])?.join(', ');
          message = `Unique constraint violation. A record with this ${target || 'field'} already exists.`;
          error = 'Conflict';
          break;
        case 'P2025': // Record not found
          status = HttpStatus.NOT_FOUND;
          message = 'The requested record was not found.';
          error = 'Not Found';
          break;
        default:
          status = HttpStatus.BAD_REQUEST;
          message = 'Database operation failed.';
          error = 'Database Error';
          details = { code: exception.code };
      }
    }
    // 3. Handle Prisma Validation Errors
    else if (exception instanceof Prisma.PrismaClientValidationError) {
      status = HttpStatus.BAD_REQUEST;
      message = 'Invalid data format provided to database.';
      error = 'Validation Error';
    }
    // 4. Handle Existing RpcException (don't wrap twice)
    else if (exception instanceof RpcException) {
      return throwError(() => exception.getError());
    }
    // 5. Handle standard Error objects
    else if (exception instanceof Error) {
      message = exception.message;
      this.logger.error(`Unhandled error: ${message}`, exception.stack);
    } else {
      this.logger.error('Unknown error type caught in filter:', exception);
    }

    const errorResponse = {
      statusCode: status,
      message: message,
      error: error,
      ...(details && { details }),
      timestamp: new Date().toISOString(),
    };

    // Log the error for debugging
    if (status >= 500) {
      this.logger.error(`Fatal Error: ${JSON.stringify(errorResponse)}`);
    } else {
      this.logger.warn(`Handled Exception: ${message} (Status: ${status})`);
    }

    // Return the formatted error as an RpcException
    return throwError(() => new RpcException(errorResponse));
  }
}

import {
  PipeTransform,
  Injectable,
  ArgumentMetadata,
  HttpStatus,
} from '@nestjs/common';
import { RpcException } from '@nestjs/microservices';
import * as Joi from 'joi';

@Injectable()
export class JoiValidationPipe implements PipeTransform {
  constructor(private schema: Joi.ObjectSchema) {}

  transform(value: any, metadata: ArgumentMetadata) {
    const { error, value: validatedValue } = this.schema.validate(value, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const messages = error.details.map((d) => d.message).join(', ');
      throw new RpcException({
        statusCode: HttpStatus.BAD_REQUEST,
        message: `Validation failed: ${messages}`,
        error: 'Bad Request',
      });
    }

    return validatedValue;
  }
}

import { Controller, Logger, UsePipes, UseFilters } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { ContactService } from './contact.service';
import { RpcExceptionFilter } from '../common/filters/rpc-exception.filter';
import { JoiValidationPipe } from '../common/pipes/joi-validation.pipe';
import { ContactInquirySchema } from './contact.validation';

@Controller()
@UseFilters(RpcExceptionFilter)
export class ContactController {
  private readonly logger = new Logger(ContactController.name);
  constructor(private readonly contactService: ContactService) {}

  @MessagePattern({ cmd: 'send_contact_inquiry' })
  @UsePipes(new JoiValidationPipe(ContactInquirySchema))
  async handleContactInquiry(
    @Payload()
    dto: {
      name: string;
      email: string;
      phone: string;
      message: string;
    },
  ) {
    this.logger.log(`Received contact inquiry from: ${dto.email}`);
    try {
      return await this.contactService.sendContactEmail(dto);
    } catch (error) {
      this.logger.error(
        `Failed to handle contact inquiry from ${dto.email}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }
}

import { Injectable, Inject, Logger } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { firstValueFrom } from 'rxjs';

@Injectable()
export class ContactService {
  private readonly logger = new Logger(ContactService.name);

  constructor(@Inject('AUTH_SERVICE') private authClient: ClientProxy) {}

  async sendContactEmail(dto: {
    name: string;
    email: string;
    phone: string;
    message: string;
  }) {
    this.logger.log(
      `Forwarding contact inquiry from ${dto.email} to Auth Service`,
    );
    try {
      return await firstValueFrom(
        this.authClient.send({ cmd: 'send_contact_email' }, dto),
      );
    } catch (error) {
      this.logger.error(
        `Failed to send contact email to Auth Service: ${error.message}`,
      );
      throw error;
    }
  }
}

import {
  Controller,
  UseGuards,
  UsePipes,
  Logger,
  UseFilters,
} from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { ContractService } from './contract.service';
import { UpdateContractStatusDto } from './dto/update-contract-status.dto';
import { AddChangeOrderDto } from './dto/add-change-order.dto';
import { AuthenticatedUser } from '../user/user.service';
import { ConTechProfileGuard, RoleGuard, Roles } from '../auth';
import { RpcExceptionFilter } from '../common/filters/rpc-exception.filter';
import { JoiValidationPipe } from '../common/pipes/joi-validation.pipe';
import {
  UpdateContractStatusSchema,
  AddChangeOrderSchema,
  ContractIdSchema,
} from './contract.validation';

@Controller()
@UseGuards(ConTechProfileGuard)
@UseFilters(RpcExceptionFilter)
export class ContractController {
  private readonly logger = new Logger(ContractController.name);
  constructor(private readonly contractsService: ContractService) {}

  @MessagePattern({ cmd: 'uploadContract' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  async uploadContract(
    @Payload()
    payload: {
      projectId: number;
      file: {
        buffer: string;
        originalname: string;
        mimetype: string;
        size: number;
      };
      user: AuthenticatedUser;
    },
  ) {
    this.logger.log(
      `Uploading contract for project ID: ${payload.projectId} by admin: ${payload.user.firebaseId}`,
    );
    try {
      return await this.contractsService.uploadAndCreateContract(
        payload.projectId,
        payload.file,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to upload contract for project ID ${payload.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'updateContractStatus' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN', 'CLIENT')
  @UsePipes(new JoiValidationPipe(UpdateContractStatusSchema))
  async updateStatus(
    @Payload()
    payload: { id: number; user: AuthenticatedUser } & UpdateContractStatusDto,
  ) {
    this.logger.log(
      `Updating status for contract ID: ${payload.id} to ${payload.status} by: ${payload.user.firebaseId}`,
    );
    try {
      return await this.contractsService.updateStatus(
        payload.id,
        payload.status,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to update status for contract ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'addChangeOrder' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  // We need to match the schema payload which has { contractId, dto, user }
  // But controller expects { id, addChangeOrderDto, user }. I'll rename in schema or adjust here.
  // Actually, I'll adjust the schema to match the controller or vice-versa.
  // The schema has { contractId, dto, user }. I'll rename fields in the controller call to match.
  async addChangeOrder(
    @Payload()
    payload: {
      id: number;
      addChangeOrderDto: AddChangeOrderDto;
      user: AuthenticatedUser;
    },
  ) {
    this.logger.log(
      `Adding change order to contract ID: ${payload.id} by admin: ${payload.user.firebaseId}`,
    );
    try {
      return await this.contractsService.addChangeOrder(
        payload.id,
        payload.addChangeOrderDto,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to add change order to contract ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'getContractViewUrl' })
  @UsePipes(new JoiValidationPipe(ContractIdSchema))
  async getSecureViewUrl(
    @Payload() payload: { id: number; user: AuthenticatedUser },
  ) {
    this.logger.log(
      `Generating secure view URL for contract ID: ${payload.id} (requested by: ${payload.user.firebaseId})`,
    );
    try {
      return await this.contractsService.generateSignedUrl(
        payload.id,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to generate signed URL for contract ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'getContractsByProjectId' })
  async getContractsByProjectId(
    @Payload() payload: { projectId: number; user: AuthenticatedUser },
  ) {
    this.logger.log(
      `Fetching contracts for project ID: ${payload.projectId} (requested by: ${payload.user.firebaseId})`,
    );
    try {
      return await this.contractsService.findByProjectId(
        payload.projectId,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to fetch contracts for project ID ${payload.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CloudinaryService } from '../cloudinary/cloudinary.service'; // Assuming you have this service
import { v2 as cloudinary } from 'cloudinary';
import { ContractStatus } from '../generated/client';
import { AddChangeOrderDto } from './dto/add-change-order.dto';
import { AuthenticatedUser, UserService } from '../user/user.service';

@Injectable()
export class ContractService {
  constructor(
    private prisma: PrismaService,
    private cloudinaryService: CloudinaryService, // Inject your Cloudinary service
    private userService: UserService,
  ) {}

  async createContract(projectId: number, contractUrl: string) {
    // Validate URL
    try {
      new URL(contractUrl);
    } catch {
      throw new BadRequestException('Invalid contract URL');
    }

    // Save the metadata to the database
    return this.prisma.contract.create({
      data: {
        projectId,
        contractFile: contractUrl,
        status: 'DRAFT', // Initial status
        changeOrders: [], // Initial empty array
      },
    });
  }

  /**
   * Upload a contract file and create a contract record
   * Handles base64 encoded files from API Gateway
   */
  async uploadAndCreateContract(
    projectId: number,
    file: {
      buffer: string;
      originalname: string;
      mimetype: string;
      size: number;
    },
    user: AuthenticatedUser,
  ) {
    // Verify project exists
    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
    });
    if (!project) {
      throw new NotFoundException('Project not found');
    }

    // Decode base64 buffer
    const fileBuffer = Buffer.from(file.buffer, 'base64');

    // Create mock Multer file for Cloudinary upload
    const mockFile = {
      buffer: fileBuffer,
      originalname: file.originalname,
      mimetype: file.mimetype,
      size: file.size,
    } as any;

    // Upload to Cloudinary as raw file (for documents like PDFs)
    const uploadResult = await this.cloudinaryService.uploadRaw(mockFile, {
      folder: `contech/contracts/${projectId}`,
      public_id: `contract_${Date.now()}`,
    });

    // Create contract record with uploaded file URL
    return this.prisma.contract.create({
      data: {
        projectId,
        contractFile: uploadResult.secure_url,
        status: 'DRAFT',
        changeOrders: [],
      },
    });
  }

  async updateStatus(id: number, status: string, user: AuthenticatedUser) {
    const contract = await this.findContractById(id, user); // RBAC included

    // Extra check: Only Pm/Admin/Client can update status.
    // Contractor probably shouldn't update contract status.
    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CONTRACTOR') {
      throw new ForbiddenException(
        'Contractors cannot update contract status.',
      );
    }

    return this.prisma.contract.update({
      where: { id },
      data: { status },
    });
  }

  async addChangeOrder(
    id: number,
    changeOrderDto: AddChangeOrderDto,
    user: AuthenticatedUser,
  ) {
    const contract = await this.findContractById(id, user);

    return this.prisma.contract.update({
      where: { id },
      data: {
        changeOrders: [
          ...((contract.changeOrders as any[]) || []),
          { ...changeOrderDto, createdAt: new Date() },
        ],
      },
    });
  }

  async generateSignedUrl(
    id: number,
    user: AuthenticatedUser,
  ): Promise<{ signedUrl: string }> {
    const contract = await this.findContractById(id, user);
    return { signedUrl: contract.contractFile };
  }

  async findByProjectId(projectId: number, user: AuthenticatedUser) {
    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
    });
    if (!project) throw new NotFoundException('Project not found');

    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to view contracts for this project.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view contracts for this project.',
      );
    }

    return this.prisma.contract.findMany({
      where: { projectId },
    });
  }

  // Helper to prevent code duplication
  private async findContractById(id: number, user: AuthenticatedUser) {
    const contract = await this.prisma.contract.findUnique({
      where: { id },
      include: { Project: true },
    });
    if (!contract) {
      throw new NotFoundException(`Contract with ID ${id} not found.`);
    }

    const project = (contract as any).Project;
    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to access this contract.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to access this contract.',
      );
    }

    return contract;
  }
}

