import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service'; // Your Prisma service
import { CloudinaryService } from '../cloudinary/cloudinary.service'; // Your Cloudinary service
import { CreateInspectionDto } from './dto/create-inspection.dto';
import { UpdateInspectionDto } from './dto/update-inspection.dto';
import { MulterFile } from 'multer';
import { AuthenticatedUser, UserService } from '../user/user.service';
@Injectable()
export class InspectionsService {
  constructor(
    private prisma: PrismaService,
    private cloudinaryService: CloudinaryService,
    private userService: UserService,
  ) {}

  async create(createInspectionDto: CreateInspectionDto, files: any[]) {
    const photoUploadPromises = files.map((file) => {
      const fileBuffer = Buffer.from(file.buffer, 'base64');

      const mockFile = {
        buffer: fileBuffer,
        originalname: file.originalname,
      } as MulterFile; // Create a mock file object for the service

      return this.cloudinaryService.uploadImage(mockFile);
    });
    const uploadResults = await Promise.all(photoUploadPromises);
    const photoUrls = uploadResults.map((result) => result.secure_url);

    // 2. Create inspection with checklist and photos as Json
    const inspection = await this.prisma.inspection.create({
      data: {
        projectId: createInspectionDto.projectId,
        inspector: createInspectionDto.inspectorId, // Mapping inspectorId to inspector
        status: createInspectionDto.status as string,
        photos: photoUrls, // Stored as Json array
        checklist: createInspectionDto.checklist as any, // Stored as Json
        isVisibleToClient: createInspectionDto.isVisibleToClient ?? false,
      },
    });

    return inspection;
  }

  async findAllForProject(
    projectId: number,
    pagination: { skip?: number; take?: number },
    user: AuthenticatedUser,
  ) {
    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
    });
    if (!project) throw new NotFoundException('Project not found');

    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to view inspections for this project.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view inspections for this project.',
      );
    }

    const { skip = 0, take = 20 } = pagination;
    const where: any = { projectId };
    if (profile.role === 'CLIENT') {
      where.isVisibleToClient = true;
    }

    return this.prisma.inspection.findMany({
      where,
      skip,
      take,
    });
  }

  async findOne(id: number, user: AuthenticatedUser) {
    const inspection = await this.prisma.inspection.findUnique({
      where: { id },
      include: { Project: true },
    });

    if (!inspection) {
      throw new NotFoundException(`Inspection with ID ${id} not found.`);
    }

    const project = (inspection as any).Project;
    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to view this inspection.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view this inspection.',
      );
    }

    return inspection;
  }

  async update(
    id: number,
    updateInspectionDto: UpdateInspectionDto,
    user: AuthenticatedUser,
  ) {
    await this.findOne(id, user);

    return this.prisma.inspection.update({
      where: { id },
      data: {
        ...updateInspectionDto,
        status: updateInspectionDto.status as string,
      } as any,
    });
  }

  async remove(id: number, user: AuthenticatedUser) {
    await this.findOne(id, user);
    return this.prisma.inspection.delete({
      where: { id },
    });
  }
}

import { LoggerService } from '@nestjs/common';
import * as winston from 'winston';

const { combine, timestamp, printf, colorize } = winston.format;

const customFormat = printf(({ level, message, timestamp }) => {
  return `[${timestamp}] ${level}: ${message}`;
});

export const winstonLogger = winston.createLogger({
  level: 'info',
  format: combine(
    colorize(),
    timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    customFormat,
  ),
  transports: [new winston.transports.Console()],
});

export class AppLogger implements LoggerService {
  log(message: string) {
    winstonLogger.info(message);
  }
  error(message: string, trace?: string) {
    winstonLogger.error(`${message} - ${trace}`);
  }
  warn(message: string) {
    winstonLogger.warn(message);
  }
  debug?(message: string) {
    winstonLogger.debug(message);
  }
  verbose?(message: string) {
    winstonLogger.verbose(message);
  }
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { MicroserviceOptions, Transport } from '@nestjs/microservices';
import * as dotenv from 'dotenv';
import { ConfigService } from '@nestjs/config';
import { ConTechProfileGuard } from './auth';
import { RpcExceptionFilter } from './common/filters/rpc-exception.filter';
import { ValidationPipe } from '@nestjs/common';

dotenv.config();

import { winstonConfig } from './winston.config';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: winstonConfig,
  });
  const PORT = parseInt(process.env.PORT || '3002', 10);
  const configService = app.get(ConfigService);

  const microservice = app.connectMicroservice({
    transport: Transport.TCP,
    options: {
      host: '0.0.0.0',
      port: PORT,
    },
  });

  // Add RabbitMQ transport for async events (optional - only if available)
  const rabbitmqUrl = process.env.RABBITMQ_URL || 'amqp://localhost';
  if (process.env.RABBITMQ_ENABLED !== 'false') {
    try {
      app.connectMicroservice({
        transport: Transport.RMQ,
        options: {
          urls: [rabbitmqUrl],
          queue: 'contech_user_events',
          exchange: 'user_events',
          exchangeType: 'fanout',
          queueOptions: {
            durable: false,
          },
          socketOptions: {
            noDelay: true,
          },
        },
      });
      console.log(`ConTech: RabbitMQ transport configured for ${rabbitmqUrl}`);
    } catch (e) {
      console.warn(`ConTech: RabbitMQ transport not available: ${e.message}`);
    }
  } else {
    console.log('ConTech: RabbitMQ disabled via RABBITMQ_ENABLED=false');
  }

  // Centralized Global Error Handling
  app.useGlobalFilters(new RpcExceptionFilter());

  // centralized Validation Handling
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      forbidNonWhitelisted: true,
    }),
  );

  // Note: Guards are applied at controller level, not globally, to allow health checks

  await app.startAllMicroservices();
  const HTTP_PORT = 4002; // Separate port for health checks
  await app.listen(HTTP_PORT, '0.0.0.0');

  console.log(`ConTech microservice: TCP port ${PORT}, HTTP port ${HTTP_PORT}`);
}
bootstrap();

