import { CreateMilestoneReviewDto } from './dto/create-milestone-review.dto';
import { FindAllMilestonesDto } from './dto/find-all-milestones.dto';
import { AuthenticatedUser, UserService } from '../user/user.service';

@Injectable()
export class MilestonesService {
  constructor(
    private prisma: PrismaService,
    private userService: UserService,
  ) {}

  async create(
    createMilestoneDto: CreateMilestoneDto,
    user: AuthenticatedUser,
  ) {
    const project = await this.prisma.project.findUnique({
      where: { id: createMilestoneDto.projectId },
    });
    if (!project) throw new NotFoundException('Project not found');

    const profile = await this.userService.getOrCreateProfile(user);
    if (
      profile.role !== 'ADMIN' &&
      project.contractorId !== user.firebaseId &&
      project.manager !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to create milestones for this project.',
      );
    }

    const milestone = await this.prisma.milestone.create({
      data: createMilestoneDto,
    });
    await this.updateProjectProgress(milestone.projectId);
    return milestone;
  }

  async findAll(dto: FindAllMilestonesDto, user: AuthenticatedUser) {
    const profile = await this.userService.getOrCreateProfile(user);
    const { projectId, status, search, page = 1, limit = 10 } = dto;

    const where: any = {};

    if (projectId) {
      const project = await this.prisma.project.findUnique({
        where: { id: projectId },
      });
      if (!project) throw new NotFoundException('Project not found');

      if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
        throw new ForbiddenException(
          'You do not have permission to view milestones for this project.',
        );
      }
      if (
        profile.role === 'CONTRACTOR' &&
        project.contractorId !== user.firebaseId
      ) {
        throw new ForbiddenException(
          'You do not have permission to view milestones for this project.',
        );
      }
      where.projectId = projectId;
    } else if (profile.role !== 'ADMIN') {
      // If no projectId, non-admin users can only see milestones for projects they are involved in
      where.Project = {
        OR: [
          { manager: user.firebaseId },
          { contractorId: user.firebaseId },
          { clientId: user.firebaseId },
        ],
      };
    }

    if (status) {
      where.status = status;
    }

    if (search) {
      where.OR = [
        { title: { contains: search, mode: 'insensitive' } },
        { description: { contains: search, mode: 'insensitive' } },
      ];
    }

    if (profile.role === 'CLIENT') {
      where.isVisibleToClient = true;
    }

    const skip = (page - 1) * limit;

    const [milestones, total] = await Promise.all([
      this.prisma.milestone.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: { Project: { select: { name: true } } },
      }),
      this.prisma.milestone.count({ where }),
    ]);

    return {
      data: milestones,
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  async findOne(id: number, user: AuthenticatedUser) {
    const milestone = await this.prisma.milestone.findUnique({
      where: { id },
      include: { Project: true },
    });
    if (!milestone) throw new NotFoundException('Milestone not found');

    const project = (milestone as any).Project;
    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT' && project.clientId !== user.firebaseId) {
      throw new ForbiddenException(
        'You do not have permission to view this milestone.',
      );
    }
    if (
      profile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view this milestone.',
      );
    }

    return milestone;
  }

  async update(
    id: number,
    updateMilestoneDto: UpdateMilestoneDto,
    user: AuthenticatedUser,
  ) {
    const milestone = await this.findOne(id, user); // RBAC Check

    // Only Admin/PM/Contractor can update milestone details (e.g. progress)
    // Client is Read-Only
    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT') {
      throw new ForbiddenException('Clients cannot update milestones.');
    }

    const result = await this.prisma.milestone.update({
      where: { id },
      data: updateMilestoneDto,
    });
    await this.updateProjectProgress(result.projectId);
    return result;
  }

  async remove(id: number, user: AuthenticatedUser) {
    const milestone = await this.findOne(id, user); // RBAC check

    const profile = await this.userService.getOrCreateProfile(user);
    // Only Admin/PM can remove. Controller already checks @Roles but double check here if needed.
    // If CONTRACTOR tries to remove via message, catch here.
    if (profile.role === 'CONTRACTOR' || profile.role === 'CLIENT') {
      throw new ForbiddenException(
        'You do not have permission to delete milestones.',
      );
    }

    const deletedMilestone = await this.prisma.milestone.delete({
      where: { id },
    });
    await this.updateProjectProgress(milestone.projectId);
    return deletedMilestone;
  }

  async submitForReview(id: number, user: AuthenticatedUser) {
    const milestone = await this.findOne(id, user); // RBAC

    const profile = await this.userService.getOrCreateProfile(user);
    if (profile.role === 'CLIENT') {
      throw new ForbiddenException(
        'Clients cannot submit milestones for review.',
      );
    }

    const result = await this.prisma.milestone.update({
      where: { id },
      data: { status: 'IN_REVIEW' },
    });
    await this.updateProjectProgress(result.projectId);
    return result;
  }

  async createReview(
    id: number,
    dto: CreateMilestoneReviewDto,
    user: AuthenticatedUser,
  ) {
    const milestone = await this.findOne(id, user); // RBAC
    const profile = await this.userService.getOrCreateProfile(user);

    if (profile.role !== 'ADMIN') {
      throw new ForbiddenException('Only Admins can review milestones.');
    }

    const updatedMilestone = await this.prisma.milestone.update({
      where: { id },
      data: {
        status: dto.status as any,
        // Any other notes?
      },
    });

    await this.updateProjectProgress(updatedMilestone.projectId);
    return updatedMilestone;
  }

  private async updateProjectProgress(projectId: number) {
    const milestones = await this.prisma.milestone.findMany({
      where: { projectId },
    });

    if (milestones.length === 0) {
      await this.prisma.project.update({
        where: { id: projectId },
        data: { progress: 0 },
      });
      return;
    }

    const approvedCount = milestones.filter(
      (m) => m.status === 'APPROVED',
    ).length;
    const progress = (approvedCount / milestones.length) * 100;

    await this.prisma.project.update({
      where: { id: projectId },
      data: { progress },
    });
  }
}

import {
  Controller,
  UseGuards,
  UsePipes,
  Logger,
  UseFilters,
} from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { ProjectsService } from './projects.service';
import { CreateProjectDto } from './dto/create-project.dto';
import { UpdateProjectDto } from './dto/update-project.dto';
import { ProjectStatus } from '../generated/client';
import { CommentsService } from './comments.service';
import { AuthenticatedUser } from '../user/user.service';
import { ConTechProfileGuard, RoleGuard, Roles } from '../auth';
import { RpcExceptionFilter } from '../common/filters/rpc-exception.filter';
import { JoiValidationPipe } from '../common/pipes/joi-validation.pipe';
import {
  CreateProjectSchema,
  UpdateProjectSchema,
  ProjectIdSchema,
  FindAllProjectsSchema,
  UpdateProjectStatusSchema,
  UpdateProjectProgressSchema,
  CreateProjectUpdateSchema,
  GetProjectUpdatesSchema,
  AddProjectDocumentSchema,
  AddProjectCommentSchema,
} from './projects.validation';

@Controller()
@UseGuards(ConTechProfileGuard)
@UseFilters(RpcExceptionFilter)
export class ProjectsController {
  private readonly logger = new Logger(ProjectsController.name);
  constructor(
    private readonly projectsService: ProjectsService,
    private readonly commentsService: CommentsService,
  ) {}

  @MessagePattern({ cmd: 'create_project' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  @UsePipes(new JoiValidationPipe(CreateProjectSchema))
  async create(
    @Payload() payload: { dto: CreateProjectDto; user: AuthenticatedUser },
  ) {
    this.logger.log(
      `Creating project "${payload.dto.name}" by admin: ${payload.user.firebaseId}`,
    );
    try {
      return await this.projectsService.create(payload.dto, payload.user);
    } catch (error) {
      this.logger.error(
        `Failed to create project "${payload.dto.name}" for user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'find_all_projects' })
  @UsePipes(new JoiValidationPipe(FindAllProjectsSchema))
  async findAll(@Payload() payload: { query: any; user: AuthenticatedUser }) {
    this.logger.log(
      `Fetching all projects with query: ${JSON.stringify(payload.query)} for user: ${payload.user?.firebaseId}`,
    );
    try {
      return await this.projectsService.findAll(payload.query, payload.user);
    } catch (error) {
      this.logger.error(
        `Failed to fetch projects with query ${JSON.stringify(payload.query)} for user ${payload.user?.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'find_project_by_id' })
  @UsePipes(new JoiValidationPipe(ProjectIdSchema))
  async findOne(@Payload() payload: { id: number; user: AuthenticatedUser }) {
    this.logger.log(
      `Fetching details for project ID: ${payload.id} by user: ${payload.user.firebaseId}`,
    );
    try {
      return await this.projectsService.findOne(payload.id, payload.user);
    } catch (error) {
      this.logger.error(
        `Failed to fetch project details for ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'find_contractor' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  async findallcontractor() {
    this.logger.log(`Fetching all contractors list (admin operation)`);
    try {
      return await this.projectsService.getContracrors();
    } catch (error) {
      this.logger.error(
        `Failed to fetch contractors: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'find_inspector' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  async findallinspector() {
    this.logger.log(`Fetching all inspectors list (admin operation)`);
    try {
      return await this.projectsService.getInspectors();
    } catch (error) {
      this.logger.error(
        `Failed to fetch inspectors: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'update_project' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  @UsePipes(new JoiValidationPipe(UpdateProjectSchema))
  async update(
    @Payload()
    payload: {
      id: number;
      dto: UpdateProjectDto;
      user: AuthenticatedUser;
    },
  ) {
    this.logger.log(
      `Updating project ID: ${payload.id} by admin: ${payload.user.firebaseId}`,
    );
    try {
      return await this.projectsService.update(
        payload.id,
        payload.dto,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to update project ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'remove_project' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN')
  @UsePipes(new JoiValidationPipe(ProjectIdSchema))
  async remove(@Payload() payload: { id: number; user: AuthenticatedUser }) {
    this.logger.log(
      `Removing project ID: ${payload.id} by admin: ${payload.user.firebaseId}`,
    );
    try {
      return await this.projectsService.remove(payload.id, payload.user);
    } catch (error) {
      this.logger.error(
        `Failed to remove project ID ${payload.id} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'update_project_status' })
  @UseGuards(RoleGuard)
  @Roles('ADMIN', 'CONTRACTOR')
  @UsePipes(new JoiValidationPipe(UpdateProjectStatusSchema))
  async updateStatus(
    @Payload()
    payload: {
      id: number;
