        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to add document to project ID ${payload.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'get_project_documents' })
  @UsePipes(new JoiValidationPipe(GetProjectUpdatesSchema))
  async getDocuments(
    @Payload()
    payload: {
      projectId: number;
      page?: number;
      pageSize?: number;
      user: AuthenticatedUser;
    },
  ) {
    this.logger.log(
      `Fetching documents for project ID: ${payload.projectId} (requested by: ${payload.user.firebaseId})`,
    );
    try {
      return await this.projectsService.getDocuments(
        payload.projectId,
        payload.user,
        payload.page,
        payload.pageSize,
      );
    } catch (error) {
      this.logger.error(
        `Failed to fetch documents for project ID ${payload.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
