  @MessagePattern({ cmd: 'add_project_comment' })
  @UsePipes(new JoiValidationPipe(AddProjectCommentSchema))
  async addComment(
    @Payload()
    payload: {
      projectId: number;
      content: string;
      user: AuthenticatedUser;
    },
  ) {
    this.logger.log(
      `Adding comment to project ID: ${payload.projectId} by: ${payload.user.firebaseId}`,
    );
    try {
      return await this.commentsService.create(
        payload.projectId,
        payload.content,
        payload.user,
      );
    } catch (error) {
      this.logger.error(
        `Failed to add comment to project ID ${payload.projectId} by user ${payload.user.firebaseId}: ${error.message}`,
        error.stack,
      );
