import {
  BadRequestException,
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateTaskDto } from './dto/create-task.dto';
import { UpdateTaskDto } from './dto/update-task.dto';
import { TaskStatus, TaskPriority, Prisma } from '../generated/client';
import { AuthenticatedUser, UserService } from '../user/user.service';

type FindTasksQuery = {
  projectId?: number;
  status?: string;
  assignedTo?: string;
  page?: number;
  pageSize?: number;
};

@Injectable()
export class TasksService {
  constructor(
    private prisma: PrismaService,
    private userService: UserService,
  ) {}

  async create(dto: CreateTaskDto, user: AuthenticatedUser) {
    const contechProfile = await this.userService.getOrCreateProfile(user);

    const project = await this.prisma.project.findUnique({
      where: { id: dto.projectId },
    });
    if (!project) throw new NotFoundException('Project not found');

    if (
      contechProfile.role !== 'ADMIN' &&
      project.contractorId !== user.firebaseId &&
      project.manager !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to create tasks for this project',
      );
    }

    if (!dto.assignedTo)
      throw new BadRequestException('Assigned user is required');
    // Ensure user has a profile and is synced from Auth
    await this.userService.ensureProfileExists(dto.assignedTo);
    const assignee = await this.userService.getUserById(dto.assignedTo);
    if (!assignee)
      throw new BadRequestException('Assigned user does not exist');

    return await this.prisma.task.create({
      data: {
        projectId: dto.projectId,
        description: dto.description,
        status: 'PENDING',
        deadline: dto.deadline ? new Date(dto.deadline) : new Date(),
        assignedTo: dto.assignedTo,
        isVisibleToClient: dto.isVisibleToClient ?? false,
      },
    });
  }

  async findByProject(
    projectId: number,
    query: FindTasksQuery,
    user: AuthenticatedUser,
  ) {
    const contechProfile = await this.userService.getOrCreateProfile(user);
    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
    });
    if (!project) throw new NotFoundException('Project not found');

    // RBAC Check
    if (
      contechProfile.role === 'CLIENT' &&
      project.clientId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view tasks for this project',
      );
    }
    if (
      contechProfile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId
    ) {
      // Contractors can only see tasks of their assigned project.
      // Assumption: If I am the contractor of the project, I see ALL tasks? Or only assigned?
      // Usually Contractor manages the project tasks. So checks project.contractorId is enough.
      throw new ForbiddenException(
        'You do not have permission to view tasks for this project',
      );
    }

    const page = query.page || 1;
    const pageSize = Math.min(query.pageSize || 20, 50);
    const skip = (page - 1) * pageSize;

    const where: Prisma.TaskWhereInput = { projectId };
    if (query.status) where.status = query.status;
    if (contechProfile.role === 'CLIENT') {
      where.isVisibleToClient = true;
    }

    const [tasks, total] = await Promise.all([
      this.prisma.task.findMany({
        where,
        skip,
        take: pageSize,
        orderBy: [{ deadline: 'asc' }],
      }),
      this.prisma.task.count({ where }),
    ]);

    const assigneeIds = tasks
      .map((t) => t.assignedTo)
      .filter((id) => id !== null);
    const assignees =
      assigneeIds.length > 0
        ? await this.userService.getUsersByIds(assigneeIds)
        : [];

    const enrichedTasks = tasks.map((task) => ({
      ...task,
      assignee: task.assignedTo
        ? assignees.find((a) => a.firebaseId === task.assignedTo) || null
        : null,
    }));

    return {
      items: enrichedTasks,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async findOne(id: number, user: AuthenticatedUser) {
    const task = await this.prisma.task.findUnique({
      where: { id },
      include: { Project: true }, // Include full project to check clientId/contractorId
    });
    if (!task) throw new NotFoundException('Task not found');

    const contechProfile = await this.userService.getOrCreateProfile(user);
    const project = (task as unknown as { Project: Record<string, any> })
      .Project;

    // RBAC Check
    if (contechProfile.role === 'CLIENT') {
      if (project.clientId !== user.firebaseId || !task.isVisibleToClient) {
        throw new ForbiddenException(
          'You do not have permission to view this task',
        );
      }
    }
    if (
      contechProfile.role === 'CONTRACTOR' &&
      project.contractorId !== user.firebaseId &&
      task.assignedTo !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to view this task',
      );
    }

    if (!task) throw new NotFoundException('Task not found');

    const assignee = task.assignedTo
      ? await this.userService.getUserById(task.assignedTo)
      : null;

    return {
      ...task,
      assignee,
    };
  }

  async update(id: number, dto: UpdateTaskDto, user: AuthenticatedUser) {
    const contechProfile = await this.userService.getOrCreateProfile(user);
    const task = await this.prisma.task.findUnique({
      where: { id },
      include: { Project: true },
    });
    if (!task) throw new NotFoundException('Task not found');

    const project = (task as any).Project as Record<string, any>;
    const canUpdate =
      contechProfile.role === 'ADMIN' ||
      project.contractorId === user.firebaseId ||
      task.assignedTo === user.firebaseId;
    if (!canUpdate)
      throw new ForbiddenException(
        'You do not have permission to update this task',
      );

    if (dto.assignedTo && dto.assignedTo !== task.assignedTo) {
      await this.userService.ensureProfileExists(dto.assignedTo);
      const assignee = await this.userService.getUserById(dto.assignedTo);
      if (!assignee)
        throw new BadRequestException('Assigned user does not exist');
    }

    const updateData: Prisma.TaskUpdateInput = {
      description: dto.description,
      status: dto.status,
      assignedTo: dto.assignedTo,
      deadline: dto.deadline ? new Date(dto.deadline) : undefined,
    };

    return await this.prisma.task.update({ where: { id }, data: updateData });
  }

  async remove(id: number, user: AuthenticatedUser) {
    const contechProfile = await this.userService.getOrCreateProfile(user);
    const task = await this.prisma.task.findUnique({
      where: { id },
      include: { Project: true },
    });
    if (!task) throw new NotFoundException('Task not found');

    const project = (task as any).Project as Record<string, any>;
    if (
      contechProfile.role !== 'ADMIN' &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to delete this task',
      );
    }

    return await this.prisma.task.delete({ where: { id } });
  }

  async updateTaskProgress(
    id: number,
    progress: number,
    user: AuthenticatedUser,
  ) {
    const task = await this.prisma.task.findUnique({
      where: { id },
      include: { Project: true },
    });
    if (!task) throw new NotFoundException('Task not found');

    const project = (task as any).Project as Record<string, any>;
    if (
      task.assignedTo !== user.firebaseId &&
      project.contractorId !== user.firebaseId
    ) {
      throw new ForbiddenException(
        'You do not have permission to update this task progress',
      );
    }

    let status = task.status;
    if (progress === 0 && status === 'IN_PROGRESS') status = 'PENDING';
    else if (progress > 0 && progress < 100 && status === 'PENDING')
      status = 'IN_PROGRESS';
    else if (progress === 100) status = 'COMPLETED';

    return await this.prisma.task.update({
      where: { id },
      data: { status },
    });
  }

  async getTaskStats(
    user: AuthenticatedUser,
    projectId?: number,
    assignedTo?: string,
  ) {
    const contechProfile = await this.userService.getOrCreateProfile(user);
    const where: Prisma.TaskWhereInput = {};
    if (projectId) where.projectId = projectId;
    if (assignedTo) where.assignedTo = assignedTo;

    // Role filtering
    if (contechProfile.role === 'CLIENT') {
      where.isVisibleToClient = true;
      // Also ensure project belongs to client if projectId provided
      if (projectId) {
        const project = await this.prisma.project.findUnique({
          where: { id: projectId },
        });
        if (project?.clientId !== user.firebaseId) {
          throw new ForbiddenException('Unauthorized');
        }
      }
    } else if (contechProfile.role === 'CONTRACTOR' && !assignedTo) {
      // If contractor wants general stats, maybe filter by their projects?
      // For now, let's keep it simple or filter by assignedTo=user.firebaseId if no assignedTo provided.
      // But contractor might want to see ALL tasks for their project.
    }

    const [
      totalTasks,
      pendingTasks,
      inProgressTasks,
      completedTasks,
      blockedTasks,
    ] = await Promise.all([
      this.prisma.task.count({ where }),
      this.prisma.task.count({ where: { ...where, status: 'PENDING' } }),
      this.prisma.task.count({ where: { ...where, status: 'IN_PROGRESS' } }),
      this.prisma.task.count({ where: { ...where, status: 'COMPLETED' } }),
      this.prisma.task.count({ where: { ...where, status: 'BLOCKED' } }),
    ]);

    return {
      total: totalTasks,
      pending: pendingTasks,
      inProgress: inProgressTasks,
      completed: completedTasks,
      blocked: blockedTasks,
      completionRate: totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0,
    };
  }
}

import {
  Controller,
  UseGuards,
  UsePipes,
  Logger,
  UseFilters,
} from '@nestjs/common';
import { MessagePattern, Payload, EventPattern } from '@nestjs/microservices';
import {
  UserService,
  AuthenticatedUser,
  ConTechUserProfile,
} from './user.service';
import { ConTechProfileGuard } from '../auth';
import { ContechRole } from '../generated/client';
import { RpcExceptionFilter } from '../common/filters/rpc-exception.filter';
import { JoiValidationPipe } from '../common/pipes/joi-validation.pipe';
import {
  GetUserProfileSchema,
  UpdateUserProfileSchema,
  SelectUserRoleSchema,
  UserCreatedEventSchema,
} from './user.validation';

@Controller()
@UseGuards(ConTechProfileGuard)
@UseFilters(RpcExceptionFilter)
export class UserController {
  private readonly logger = new Logger(UserController.name);
  constructor(private readonly userService: UserService) {}

  @MessagePattern({ cmd: 'get_contech_profile' })
  @UsePipes(new JoiValidationPipe(GetUserProfileSchema))
  async getProfile(
    @Payload() payload: { user: AuthenticatedUser },
  ): Promise<ConTechUserProfile> {
    this.logger.log(`Fetching profile for user: ${payload.user.firebaseId}`);
    try {
      return await this.userService.getOrCreateProfile(payload.user);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Failed to fetch profile for user ${payload.user.firebaseId}: ${errorMessage}`,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'create_contech_profile' })
  @UsePipes(new JoiValidationPipe(GetUserProfileSchema))
  async createProfile(@Payload() payload: { user: AuthenticatedUser }) {
    this.logger.log(`Creating profile for user: ${payload.user.firebaseId}`);
    try {
      return await this.userService.getOrCreateProfile(payload.user);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Failed to create profile for user ${payload.user.firebaseId}: ${errorMessage}`,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'update_contech_profile' })
  @UsePipes(new JoiValidationPipe(UpdateUserProfileSchema))
  async updateProfile(
    @Payload()
    payload: {
      user: AuthenticatedUser;
      updateData: Partial<ConTechUserProfile>;
    },
  ) {
    this.logger.log(`Updating profile for user: ${payload.user.firebaseId}`);
    try {
      return await this.userService.updateProfile(
        payload.user,
        payload.updateData,
      );
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Failed to update profile for user ${payload.user.firebaseId}: ${errorMessage}`,
      );
      throw error;
    }
  }

  @MessagePattern({ cmd: 'select_contech_role' })
  @UsePipes(new JoiValidationPipe(SelectUserRoleSchema))
  async selectRole(@Payload() payload: { userId: string; role: ContechRole }) {
    this.logger.log(
      `Selecting role ${payload.role} for user: ${payload.userId}`,
    );
    try {
      return await this.userService.selectRole(payload.userId, payload.role);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Failed to select role for user ${payload.userId}: ${errorMessage}`,
      );
      throw error;
    }
  }

  @EventPattern('user_created')
  @UsePipes(new JoiValidationPipe(UserCreatedEventSchema))
  async handleUserCreated(
    @Payload()
    payload: {
      userId: string;
      email: string;
      role: string;
      globalRole?: string;
    },
  ) {
    this.logger.log(
      `Handling user_created event for user: ${payload.userId} (${payload.email})`,
    );
    try {
      const authenticatedUser: AuthenticatedUser = {
        firebaseId: payload.userId,
        email: payload.email,
        firstname: '',
        lastname: '',
        role: payload.role,
        globalRole: payload.globalRole,
        status: 'ACTIVE',
      };
      await this.userService.getOrCreateProfile(authenticatedUser);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Failed to handle user_created event for user ${payload.userId}: ${errorMessage}`,
      );
    }
  }
}

